use xiom.io;

use xiom.string;
fn main() {
  let name: Str = "Alex";
  var points: Int = 0;

  let greeting: Str = string.str_concat("Player: ", string.str_upper(name));
  io.println(greeting);

  var round: Int = 1;
  while round <= 5 {
    points += 10;
    round += 1;
  }

  if points > 50 {
    io.println("You passed!");
  } else {
    io.println("Try again!");
  }

  let name_len: Int = string.str_len(name);
  io.print("Your name has ");
  io.print("4");
  io.println(" letters.");
}
